export let SAGA=null;
export async function loadSaga(fetcher=fetch){const r=await fetcher('saga.json?v=25');if(!r.ok)throw Error('História indisponível');const data=await r.json();if(data.schemaVersion!==1||data.acts?.length!==6||data.acts.some(a=>a.steps?.length!==5||!a.id||!a.reward))throw Error('História incompatível');SAGA=data;return data;}
export function sagaState(p){p.saga||={act:0,step:0,count:0,titles:[]};return p.saga;}
export function sagaObjective(p){if(!SAGA)return null;const s=sagaState(p),a=SAGA.acts[s.act];return a?{act:a,step:a.steps[s.step],state:s,locked:p.level<a.level,ready:s.step===a.steps.length}:null;}
export function sagaProgress(p,event){const q=sagaObjective(p);if(!q||q.ready||q.locked||event.training||event.region!==q.act.region)return false;const k=q.step;if(k.type!==event.type)return false;if(k.type==='visit'&&(p.zone!=='coast'||Math.hypot(p.x-k.x,p.y-k.y)>2))return false;if(k.type==='kill'&&(event.zone!=='coast'||event.level<q.act.level))return false;if(k.type==='boss'&&(event.division!==k.division||event.level<q.act.level))return false;q.state.count++;if(q.state.count>=k.target){q.state.step++;q.state.count=0;return true;}return false;}
export function claimSaga(p){const q=sagaObjective(p);if(!q?.ready)return{ok:false,reason:'Conclua os cinco objetivos do ato.'};if(p.zone!=='coast'||Math.hypot(p.x-12,p.y-12)>3)return{ok:false,reason:'Retorne à Ilyra para encerrar o ato.'};p.materials||={};p.gold+=q.act.reward.gold;for(const [key,value] of [['Pluma Astral',q.act.reward.plumes],['Essência de Aura',q.act.reward.essences]])p.materials[key]=(p.materials[key]||0)+value;q.state.titles.push(q.act.trophy);q.state.act++;q.state.step=0;q.state.count=0;return{ok:true,title:q.act.trophy,outcome:q.act.outcome};}
